using System;using System.IO;using System.Linq;using System.Text;using System.Reflection;using UnityEngine;using UnityEngine.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using UnityEditor;using UnityEditor.SceneManagement;
namespace CodexOutTransfer {
 public static class OutFocusRetune {
 const string W="C:/Users/lenovo/Documents/Codex/2026-10-16/new-chat/work/",O="C:/Users/lenovo/Documents/Codex/2026-10-16/new-chat/outputs/";
 static Camera Camera(){var s=SceneManager.GetSceneByPath("Assets/ArtStyleTest/Scenes/out.unity");if(!s.IsValid()||!s.isLoaded||EditorApplication.isPlaying)throw new Exception("Open out in Edit mode");return s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Camera>(true)).First(c=>c.transform.parent&&c.transform.parent.name=="xiangjipingtai"&&c.name=="Camera");}
 static void Capture(Camera c,string name){typeof(OutSceneTransfer).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{c,O+name});}
 static GameObject House(Camera c){return c.gameObject.scene.GetRootGameObjects().FirstOrDefault(g=>g.name.Equals("house",StringComparison.OrdinalIgnoreCase));}
 static string ProtectedSignature(Camera c){var b=new StringBuilder();var scene=c.gameObject.scene;foreach(var t in scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true))){b.AppendLine(t.GetInstanceID()+" "+t.name+" "+t.gameObject.tag+" "+t.gameObject.activeSelf+" "+t.localPosition.ToString("R")+" "+t.localRotation.ToString("R")+" "+t.localScale.ToString("R"));var r=t.GetComponent<Renderer>();if(r)b.AppendLine("renderer "+r.enabled+" "+string.Join(",",r.sharedMaterials.Select(m=>m?AssetDatabase.GetAssetPath(m):"null")));var light=t.GetComponent<Light>();if(light)b.AppendLine("light "+EditorJsonUtility.ToJson(light));}
 b.AppendLine("camera "+c.transform.position.ToString("R")+" "+c.transform.rotation.ToString("R")+" fov="+c.fieldOfView+" near="+c.nearClipPlane+" far="+c.farClipPlane+" rect="+c.rect+" renderer="+EditorJsonUtility.ToJson(c.GetUniversalAdditionalCameraData()));
 foreach(var v in UnityEngine.Object.FindObjectsOfType<Volume>()){b.AppendLine("volume "+v.GetInstanceID()+" "+v.enabled+" "+v.priority+" "+v.weight+" "+AssetDatabase.GetAssetPath(v.sharedProfile));if(v.sharedProfile)foreach(var component in v.sharedProfile.components.Where(x=>!(x is DepthOfField)))b.AppendLine("grade "+EditorJsonUtility.ToJson(component));}var air=MeadowAtmosphere.active;if(air)b.AppendLine("atmosphere "+JsonUtility.ToJson(air));var style=UnityEngine.Object.FindObjectOfType<MeadowPainterlyStyle>();if(style)b.AppendLine("style "+JsonUtility.ToJson(style));var f=c.GetComponent<MeadowCameraFocus>();b.AppendLine("aerial "+f.aerialPerspective+" "+f.hazeStart+" "+f.hazeEnd+" "+f.hazeStrength+" "+f.hazeColour);b.AppendLine("ambient "+RenderSettings.ambientMode+" "+RenderSettings.ambientSkyColor+" "+RenderSettings.ambientEquatorColor+" "+RenderSettings.ambientGroundColor+" "+RenderSettings.reflectionIntensity);return b.ToString();}
 [MenuItem("Tools/Out Scene Transfer/Inspect Focus And House Distance")]
 public static void Inspect(){var b=new StringBuilder();try{var c=Camera();var f=c.GetComponent<MeadowCameraFocus>();var house=House(c);b.AppendLine("camera="+c.transform.position.ToString("R")+" rotation="+c.transform.rotation.eulerAngles.ToString("R")+" fov="+c.fieldOfView+" focus="+f.EffectiveFocusDistance+" focalLength="+f.focalLength+" aperture="+f.aperture+" focusTarget="+(f.focusTarget?f.focusTarget.name:"none"));if(!house)throw new Exception("House not found");b.AppendLine("house="+house.transform.position.ToString("R")+" rootDepth="+Vector3.Dot(house.transform.position-c.transform.position,c.transform.forward));foreach(var r in house.GetComponentsInChildren<Renderer>(true).Take(30)){var p=c.WorldToViewportPoint(r.bounds.center);b.AppendLine("part="+r.name+" depth="+p.z+" viewport="+p.ToString("F3")+" bounds="+r.bounds);}
 File.WriteAllText(W+"out_focus_protected_before.txt",ProtectedSignature(c));File.Copy(c.gameObject.scene.path,W+"out_before_focus_retune.unity",true);File.WriteAllText(W+"out_focus_settings_before.json",JsonUtility.ToJson(f,true));File.Copy(AssetDatabase.GetAssetPath(f.focusProfile),W+"out_focus_profile_before.asset.txt",true);Capture(c,"Out_focus_before_retune.png");b.AppendLine("backedUp=True");}catch(Exception e){b.AppendLine(e.ToString());}File.WriteAllText(W+"out_focus_house_inspection.txt",b.ToString());}
 [MenuItem("Tools/Out Scene Transfer/Retune Focus On House Only")]
 public static void Retune(){var b=new StringBuilder();try{if(!File.ReadAllText(W+"out_focus_house_inspection.txt").Contains("backedUp=True"))throw new Exception("Inspect first");var c=Camera();var f=c.GetComponent<MeadowCameraFocus>();var house=House(c);var signature=ProtectedSignature(c);f.focusTarget=house.transform;f.focusDistance=Mathf.Max(.5f,Vector3.Dot(house.transform.position-c.transform.position,c.transform.forward));f.focalLength=75;f.aperture=4;f.depthOfField=true;f.Apply();Capture(c,"Out_focus_house_preview.png");if(signature!=ProtectedSignature(c)){File.WriteAllText(W+"out_focus_protected_after.txt",ProtectedSignature(c));throw new Exception("Unrelated scene setting changed");}EditorUtility.SetDirty(f);DepthOfField dof;f.focusProfile.TryGet(out dof);EditorUtility.SetDirty(dof);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(c.gameObject.scene);if(!EditorSceneManager.SaveScene(c.gameObject.scene))throw new Exception("Save failed");Selection.activeGameObject=c.gameObject;SceneView.RepaintAll();b.AppendLine("focusTarget="+house.name+" focusMetres="+f.EffectiveFocusDistance+" focalLength="+f.focalLength+" aperture="+f.aperture+" protectedSettingsUnchanged=True saved=True");}catch(Exception e){b.AppendLine(e.ToString());Debug.LogException(e);}File.WriteAllText(W+"out_focus_retune.txt",b.ToString());}
 }
}
